//! Inserting rows: one `INSERT` per entry, all in one transaction, returning the inserted primary keys.

use crate::Assignment;
use crate::Meta;
use crate::Model;
use crate::TableMeta;
use crate::query::Bind;
use crate::query::render::push_identifier;
use sqlx::Acquire;
use sqlx::AssertSqlSafe;
use sqlx::FromRow;
use sqlx::Postgres;
use sqlx::postgres::PgArguments;
use sqlx::postgres::PgRow;
use std::fmt;

/// The insert view of an input, generated by `#[derive(DbInsert)]`.
pub trait InsertRow {
    type Model: Model;

    /// The row an insert returns: the model's primary key.
    type Key: for<'r> FromRow<'r, PgRow> + Send + Unpin;

    /// Provided columns in declaration order. An absent optional column is not listed; `value: None` writes SQL `NULL`.
    fn columns(&self) -> Vec<Assignment<'_>>;
}

/// A batch of inserts: one `INSERT` per entry in one transaction, returning the inserted primary keys.
pub struct InsertQuery<P: InsertRow> {
    entries: Vec<P>,
}

/// One rendered `INSERT` of an insert entry.
#[derive(Debug)]
pub struct RenderedInsert {
    pub sql: String,
    pub arguments: PgArguments,
    /// The bound values as JSON, for assertions and logs.
    pub values: Vec<serde_json::Value>,
}

impl<P: InsertRow> InsertQuery<P> {
    pub fn new(entries: impl IntoIterator<Item = P>) -> Self {
        Self {
            entries: entries.into_iter().collect(),
        }
    }

    /// One statement per entry, in entry order.
    pub fn render(&self) -> Result<Vec<RenderedInsert>, InsertError> {
        let meta = match P::Model::meta() {
            Meta::Table(meta) => meta,
            Meta::SubQuery(_) | Meta::Fragment(_) => return Err(InsertError::NotATable),
        };

        self.entries
            .iter()
            .map(|entry| render_entry(meta, entry))
            .collect()
    }

    /// Renders first, then runs one transaction (`&mut Transaction` nests a savepoint); a failure rolls all back.
    pub async fn execute<'c, A>(self, acquirer: A) -> Result<Vec<P::Key>, InsertError>
    where
        A: Acquire<'c, Database = Postgres>,
    {
        if self.entries.is_empty() {
            return Ok(Vec::new());
        }

        let statements = self.render()?;
        let mut transaction = acquirer.begin().await?;
        let mut rows = Vec::with_capacity(statements.len());

        for (index, statement) in statements.into_iter().enumerate() {
            let row = sqlx::query_as_with::<_, P::Key, _>(
                AssertSqlSafe(statement.sql),
                statement.arguments,
            )
            .fetch_one(&mut *transaction)
            .await;

            match row {
                Ok(row) => rows.push(row),
                Err(sqlx::Error::RowNotFound) => {
                    return Err(InsertError::NotInserted { index });
                }
                Err(error) => return Err(InsertError::Sqlx(error)),
            }
        }

        transaction.commit().await?;

        Ok(rows)
    }
}

/// Everything an insert batch can be rejected for.
#[derive(Debug)]
pub enum InsertError {
    /// The model is a fragment or a subquery and has no table.
    NotATable,
    /// An `INSERT ... RETURNING <primary key>` did not return exactly one row.
    NotInserted { index: usize },
    /// Encode, execute, decode, savepoint or commit failure.
    Sqlx(sqlx::Error),
}

impl fmt::Display for InsertError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            InsertError::NotATable => formatter
                .write_str("an insert batch needs a table model, not a fragment or subquery"),
            InsertError::NotInserted { index } => {
                write!(formatter, "insert entry {index} returned no primary key")
            }
            InsertError::Sqlx(error) => error.fmt(formatter),
        }
    }
}

impl std::error::Error for InsertError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            InsertError::Sqlx(error) => Some(error),
            _ => None,
        }
    }
}

impl From<sqlx::Error> for InsertError {
    fn from(error: sqlx::Error) -> Self {
        InsertError::Sqlx(error)
    }
}

fn render_entry<P: InsertRow>(meta: &TableMeta, entry: &P) -> Result<RenderedInsert, InsertError> {
    let mut provided = entry.columns();
    add_updated_at(meta, &mut provided);

    let mut renderer = InsertRenderer::default();

    renderer.sql.push_str("INSERT INTO ");
    push_identifier(&mut renderer.sql, meta.table);

    if provided.is_empty() {
        renderer.sql.push_str(" DEFAULT VALUES");
        push_returning(meta, &mut renderer.sql);

        return Ok(RenderedInsert {
            sql: renderer.sql,
            arguments: renderer.arguments,
            values: renderer.values,
        });
    }

    let assignments: Vec<Assignment<'_>> = meta
        .columns
        .iter()
        .filter_map(|column| {
            provided
                .iter()
                .find(|assignment| assignment.column == column.name())
                .copied()
        })
        .collect();
    debug_assert_eq!(
        assignments.len(),
        provided.len(),
        "an insert input named a column outside the model"
    );

    renderer.sql.push_str(" (");
    for (position, assignment) in assignments.iter().enumerate() {
        if position > 0 {
            renderer.sql.push_str(", ");
        }
        push_identifier(&mut renderer.sql, assignment.column);
    }

    renderer.sql.push_str(") VALUES (");
    for (position, assignment) in assignments.iter().enumerate() {
        if position > 0 {
            renderer.sql.push_str(", ");
        }
        match assignment.value {
            Some(value) => renderer.push(value)?,
            None => renderer.sql.push_str("NULL"),
        }
    }

    renderer.sql.push(')');
    push_returning(meta, &mut renderer.sql);

    Ok(RenderedInsert {
        sql: renderer.sql,
        arguments: renderer.arguments,
        values: renderer.values,
    })
}

/// The inserted row is identified by its primary key, so `RETURNING` names those columns instead of the whole row.
fn push_returning(meta: &TableMeta, sql: &mut String) {
    sql.push_str(" RETURNING ");

    for (position, column) in meta.primary_key.iter().enumerate() {
        if position > 0 {
            sql.push_str(", ");
        }
        push_identifier(sql, column);
    }
}

/// An imported row supplies `created_at` but not `updated_at`; reuse it so `now()` does not mark the row modified.
fn add_updated_at(meta: &TableMeta, assignments: &mut Vec<Assignment<'_>>) {
    let (Some(created_at), Some(updated_at)) = (meta.created_at, meta.updated_at) else {
        return;
    };

    if assignments
        .iter()
        .any(|assignment| assignment.column == updated_at)
    {
        return;
    }

    let Some(created) = assignments
        .iter()
        .find(|assignment| assignment.column == created_at)
        .copied()
    else {
        return;
    };

    assignments.push(Assignment {
        column: updated_at,
        value: created.value,
    });
}

#[derive(Default)]
struct InsertRenderer {
    sql: String,
    arguments: PgArguments,
    values: Vec<serde_json::Value>,
    placeholders: usize,
}

impl InsertRenderer {
    fn push(&mut self, value: &dyn Bind) -> Result<(), InsertError> {
        self.placeholders += 1;
        self.sql.push('$');
        self.sql.push_str(&self.placeholders.to_string());
        value.bind(&mut self.arguments)?;
        self.values.push(value.as_json());

        Ok(())
    }
}
